Q: Why is this phone number not recognised in iOS Safari? A: <p>The issue occurs because Safari's pattern recognition can be inconsistent when phone numbers are mixed with specific keywords like &quot;Bound&quot;. To fix this and ensure 100% reliability, you should take manual control.</p>
<ol>
<li><p><strong>Disable Auto-Detection</strong> Add this meta tag to your <code>&lt;head&gt;</code> section to stop Safari from guessing:</p>
<p>HTML</p>
<pre class="lang-html prettyprint-override"><code>&lt;meta name=&quot;format-detection&quot; content=&quot;telephone=no&quot;&gt;
</code></pre>
</li>
<li><p><strong>Use Manual <code>tel:</code> Links</strong> Wrap your phone numbers in an anchor tag. This is the standard way to ensure it works across all mobile browsers:</p>
<p>HTML</p>
<pre class="lang-html prettyprint-override"><code>&lt;p&gt;Bound &lt;a href=&quot;tel:1-555-555-5555&quot;&gt;1-555-555-5555&lt;/a&gt;&lt;/p&gt;
</code></pre>
</li>
<li><p><strong>Style for Consistency (CSS)</strong> Use this CSS to prevent the default blue link style while keeping it interactive on mobile:</p>
<p>CSS</p>
<pre class="lang-css prettyprint-override"><code>a[href^=&quot;tel&quot;] {
    color: inherit;
    text-decoration: none;
}

@media (max-width: 768px) {
    a[href^=&quot;tel&quot;] {
        color: #007bff;
        text-decoration: underline;
    }
}
</code></pre>
</li>
</ol>
<p><strong>Demo:</strong> You can check the fix here <a href="https://codepen.io/aymandevoffical-stack/pen/pvEYRRK" rel="nofollow noreferrer">https://codepen.io/aymandevoffical-stack/pen/pvEYRRK</a></p>

Q: How to get camera device name in OpenCV? A: <p>This is more close to what you want(Note that, all <strong>STRING</strong> types are std::string):</p>
<pre><code>int _GetUSBCameraDevicesList(std::vector&lt;__STRING__&gt;&amp; list, std::vector&lt;__STRING__&gt;&amp; devicePaths)
{
    //COM Library Initialization
    //comInit();

    ICreateDevEnum* pDevEnum = NULL;
    IEnumMoniker* pEnum = NULL;
    int deviceCounter = 0;
    CoInitialize(NULL);

    HRESULT hr = CoCreateInstance(CLSID_SystemDeviceEnum, NULL,
        CLSCTX_INPROC_SERVER, IID_ICreateDevEnum,
        reinterpret_cast&lt;void**&gt;(&amp;pDevEnum));


    if (SUCCEEDED(hr))
    {
        // Create an enumerator for the video capture category.
        hr = pDevEnum-&gt;CreateClassEnumerator(
            CLSID_VideoInputDeviceCategory,
            &amp;pEnum, 0);

        if (hr == S_OK) {

            printf(&quot;SETUP: Looking For Capture Devices\n&quot;);
            IMoniker* pMoniker = NULL;

            while (pEnum-&gt;Next(1, &amp;pMoniker, NULL) == S_OK) {

                IPropertyBag* pPropBag;
                hr = pMoniker-&gt;BindToStorage(0, 0, IID_IPropertyBag,
                    (void**)(&amp;pPropBag));

                if (FAILED(hr)) {
                    pMoniker-&gt;Release();
                    continue;  // Skip this one, maybe the next one will work.
                }


                // Find the description or friendly name.
                VARIANT varName;
                VariantInit(&amp;varName);
                hr = pPropBag-&gt;Read(L&quot;Description&quot;, &amp;varName, 0);

                if (FAILED(hr)) hr = pPropBag-&gt;Read(L&quot;FriendlyName&quot;, &amp;varName, 0);

                if (SUCCEEDED(hr))
                {

                    hr = pPropBag-&gt;Read(L&quot;FriendlyName&quot;, &amp;varName, 0);

                    int count = 0;
                    char tmp[255] = { 0 };
                    //int maxLen = sizeof(deviceNames[0]) / sizeof(deviceNames[0][0]) - 2;
                    while (varName.bstrVal[count] != 0x00 &amp;&amp; count &lt; 255)
                    {
                        tmp[count] = (char)varName.bstrVal[count];
                        count++;
                    }
                    list.emplace_back(tmp);
                    //deviceNames[deviceCounter][count] = 0;

                    //if (!silent) DebugPrintOut(&quot;SETUP: %i) %s\n&quot;, deviceCounter, deviceNames[deviceCounter]);


                    // then read Device Path
                    {
                        VARIANT DP_Path;
                        VariantInit(&amp;DP_Path);

                        hr = pPropBag-&gt;Read(L&quot;DevicePath&quot;, &amp;DP_Path, 0);

                        if (SUCCEEDED(hr))
                        {
                            int __count = 0;
                            char __tmp[255] = { 0 };
                            while (DP_Path.bstrVal[__count] != 0x00 &amp;&amp; __count &lt; 255)
                            {
                                __tmp[__count] = (char)DP_Path.bstrVal[__count];
                                __count++;
                            }

                            devicePaths.emplace_back(__tmp);
                        }
                    }
                }

                pPropBag-&gt;Release();
                pPropBag = NULL;

                pMoniker-&gt;Release();
                pMoniker = NULL;

                deviceCounter++;
            }

            pDevEnum-&gt;Release();
            pDevEnum = NULL;

            pEnum-&gt;Release();
            pEnum = NULL;
        }

        //if (!silent) DebugPrintOut(&quot;SETUP: %i Device(s) found\n\n&quot;, deviceCounter);
    }

    //comUnInit();

    return deviceCounter;
}
</code></pre>
<p>Just pass two std::vectorstd::string() to get the list of all connected devices and their paths(Paths may be used to compare device identity if two device have the same friendly name).</p>

Q: Imgproc.copyMakeBorder in OpenCV 3.1? A: <p>You can use OpenCV 3.1 only. <code>copyMakeBorder</code> has been moved to <code>Core</code>, and you can call it like:</p>

<pre><code>int border = 2;
Core.copyMakeBorder(src, dst, border, border, border, border, Core.BORDER_REFLECT_101);
</code></pre>
